function check(input, actual, expected) {
  const [target, dictionary] = input;
  // Split an abbreviation into letters and numbers; null if it is not well formed.
  const parse = (abbr) => {
    if (typeof abbr !== 'string') return null;
    const tokens = [];
    let i = 0;
    while (i < abbr.length) {
      if (abbr[i] >= '0' && abbr[i] <= '9') {
        if (abbr[i] === '0') return null;
        let j = i;
        while (j < abbr.length && abbr[j] >= '0' && abbr[j] <= '9') j++;
        tokens.push(Number(abbr.slice(i, j)));
        i = j;
      } else if (abbr[i] >= 'a' && abbr[i] <= 'z') {
        tokens.push(abbr[i]);
        i++;
      } else return null;
    }
    return tokens;
  };
  const matches = (tokens, word) => {
    let at = 0;
    for (const token of tokens) {
      if (typeof token === 'number') at += token;
      else if (at < word.length && word[at] === token) at++;
      else return false;
    }
    return at === word.length;
  };
  const mine = parse(actual), best = parse(expected);
  if (!mine || !best || mine.length !== best.length) return false;
  return matches(mine, target) && dictionary.every(word => !matches(mine, word));
}

