function validate([target, dictionary]) {
  const m = target.length, n = dictionary.length;
  if (m < 1 || m > 21) return 'target needs 1 to 21 letters.';
  if (!/^[a-z]+$/.test(target)) return 'target uses only lowercase English letters.';
  if (n > 1000) return 'dictionary holds at most 1000 words.';
  if (dictionary.some(word => word.length < 1 || word.length > 100 || !/^[a-z]+$/.test(word))) return 'Each dictionary word has 1 to 100 lowercase letters.';
  if (n > 0 && Math.log2(n) + m > 21) return 'log2(dictionary.length) + target.length must be at most 21.';
  if (dictionary.includes(target)) return 'dictionary must not contain target.';
  return null;
}

