function minAbbreviation(target, dictionary) {
  const m = target.length;
  const diffs = [];
  let candidates = 0;
  for (const word of dictionary) {
    if (word.length !== m) continue;
    let diff = 0;
    for (let i = 0; i < m; i++) {
      if (word[i] !== target[i]) diff |= 1 << i;
    }
    diffs.push(diff);
    candidates |= diff;
  }
  if (diffs.length === 0) return String(m);

  const lengthOf = (mask) => {
    let length = 0;
    for (let i = 0; i < m; i++) {
      const kept = mask & (1 << i);
      const runStarts = i === 0 || mask & (1 << (i - 1));
      if (kept || runStarts) length++;
    }
    return length;
  };

  let bestMask = (1 << m) - 1;
  let bestLength = m;
  const search = (start, mask) => {
    const length = lengthOf(mask);
    if (length >= bestLength) return;
    if (diffs.every((diff) => (mask & diff) !== 0)) {
      bestMask = mask;
      bestLength = length;
      return;
    }
    for (let i = start; i < m; i++) {
      if (candidates & (1 << i)) search(i + 1, mask | (1 << i));
    }
  };
  search(0, 0);

  let result = '';
  let skipped = 0;
  for (let i = 0; i < m; i++) {
    if (bestMask & (1 << i)) {
      if (skipped > 0) result += skipped;
      result += target[i];
      skipped = 0;
    } else {
      skipped++;
    }
  }
  if (skipped > 0) result += skipped;
  return result;
}

