function minAbbreviation(target, dictionary) {
  const m = target.length;
  const sameLength = dictionary.filter(word => word.length === m);
  // Walk an abbreviation against a word, the way Valid Word Abbreviation does.
  const fits = (abbr, word) => {
    let i = 0, j = 0;
    while (i < abbr.length) {
      if (abbr[i] >= '0' && abbr[i] <= '9') {
        let count = 0;
        while (i < abbr.length && abbr[i] >= '0' && abbr[i] <= '9') count = count * 10 + Number(abbr[i++]);
        j += count;
      } else {
        if (j >= word.length || word[j] !== abbr[i]) return false;
        i++; j++;
      }
    }
    return j === word.length;
  };
  // Try every abbreviation of length 1, then 2, ... and return the first one no word fits.
  for (let goal = 1; goal <= m; goal++) {
    let found = null;
    const build = (pos, text, size, afterNumber) => {
      if (found !== null || size > goal) return;
      if (pos === m) {
        if (size === goal && sameLength.every(word => !fits(text, word))) found = text;
        return;
      }
      build(pos + 1, text + target[pos], size + 1, false);
      if (!afterNumber) for (let end = pos + 1; end <= m; end++) build(end, text + (end - pos), size + 1, true);
    };
    build(0, '', 0, false);
    if (found !== null) return found;
  }
  return target;
}

