function generate(rand, size) {
  const large = size === 'large';
  const letters = rand() < 0.5 ? 'ab' : 'abc';
  const word = (length) => Array.from({ length }, () => letters[Math.floor(rand() * letters.length)]).join('');
  const m = large ? 11 + Math.floor(rand() * 6) : 1 + Math.floor(rand() * 7);
  const n = large ? Math.min(1000, 2 ** (21 - m)) : Math.floor(rand() * 7);
  const target = word(m);
  const dictionary = [];
  while (dictionary.length < n) {
    let candidate;
    if (rand() < 0.2) candidate = word(1 + Math.floor(rand() * (m + 2)));
    else {
      // Mostly near-copies of target, so abbreviations collide.
      const chars = target.split('');
      const changes = 1 + Math.floor(rand() * 3);
      for (let c = 0; c < changes; c++) chars[Math.floor(rand() * m)] = letters[Math.floor(rand() * letters.length)];
      candidate = chars.join('');
    }
    if (candidate !== target) dictionary.push(candidate);
  }
  return [target, dictionary];
}
